+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #e0e0e0;
+    margin-bottom: 0.75rem;
+    display: block;
+}
+
+/* Toggle */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+}
+
+.toggle-label {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    cursor: pointer;
+    padding: 0.5rem 0;
+}
+
+.toggle-switch {
+    width: 40px;
+    height: 20px;
+    cursor: pointer;
+}
+
+/* Muted Channels */
+.muted-channels {
+    margin-bottom: 1.5rem;
+}
+
+.muted-channels h4 {
+    margin: 0 0 0.75rem;
+    color: #555;
+}
+
+.channel-label {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.4rem 0;
+    cursor: pointer;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 1rem 1.25rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+    color: #333;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Security */
+.security-item {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 1rem 0;
+    border-bottom: 1px solid #e0e0e0;
+    margin-bottom: 1.5rem;
+}
+
+.security-info {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.security-info h4 {
+    margin: 0;
+}
+
+.status-indicator {
+    padding: 0.25rem 0.75rem;
+    border-radius: 12px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+.status-enabled {
+    background: #e8f5e9;
+    color: #2e7d32;
+}
+
+.status-disabled {
+    background: #ffebee;
+    color: #c62828;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    color: #888;
+    font-style: italic;
+}
+
+/* Sessions Table */
+.sessions-section h4 {
+    margin: 0 0 1rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 12px;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.dialog h4 {
+    margin: 0 0 0.75rem;
+}
+
+.dialog p {
+    color: #555;
+    margin-bottom: 1.25rem;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Radio Groups */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance Preview */
+.preview-area {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin: 1.5rem 0;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin: 0 0 0.75rem;
+    font-size: 0.9rem;
+    color: #888;
+    text-transform: uppercase;
+    letter-spacing: 0.5px;
+}
+
+.preview-card {
+    background: rgba(0, 0, 0, 0.03);
+    border-radius: 6px;
+    padding: 1rem;
+    margin-top: 0.75rem;
+}
+
+.preview-card .preview-title {
+    display: block;
+    font-weight: 600;
+    margin-bottom: 0.4rem;
+}
+
+.preview-card .preview-body {
+    color: #666;
+}
+
+/* Preview Theme Variants */
+.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    background: rgba(255, 255, 255, 0.05);
+}
+
+.preview-theme-dark .preview-card .preview-body {
+    color: #aaa;
+}
+
+.preview-theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+/* Preview Font Sizes */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Preview Compact Mode */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+

